<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { FondoCajaChicaResumen, RendicionCajaChica, RendicionCajaChicaFiltros, TipoRendicionCajaChica } from '../interfaces/rendicion-caja-chica.interface'
import { cambiarEstadoRendicionCajaChica, listarRendicionesCajaChica, obtenerRendicionCajaChica } from '../services/rendicion-caja-chica'
const blank = (): RendicionCajaChicaFiltros => ({ tipo_rendicion: '', tipo_fondo_caja_chica_id: '', fecha_desde: '', fecha_hasta: '', numero_rendicion: '' })
const filters = reactive(blank()), rows = ref<RendicionCajaChica[]>([]), funds = ref<FondoCajaChicaResumen[]>([]), page = ref(1), lastPage = ref(1), total = ref(0), loading = ref(false), error = ref(''), success = ref(''), detail = ref<RendicionCajaChica | null>(null)
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
const money = (v: number) => new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
const date = (v?: string) => v ? new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE') : '-'
const typeName = (v: TipoRendicionCajaChica) => ({FONDO_FIJO:'Rendición de fondo fijo',GASTO_DIRECTO:'Rendición de gasto directo',ANTICIPO_VIATICO:'Rendición de anticipos - viáticos'}[v])
const percent = (x: RendicionCajaChica) => x.porcentaje_contabilizacion ?? (x.documentos_totales ? Math.round(((x.documentos_contabilizados||0)/x.documentos_totales)*100) : 0)
async function load(next=1) { loading.value=true;error.value='';try{const r=await listarRendicionesCajaChica(filters,next);rows.value=r.data;funds.value=r.tipos_fondo||funds.value;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false} }
async function view(item:RendicionCajaChica){loading.value=true;try{detail.value=await obtenerRendicionCajaChica(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:RendicionCajaChica){const action=item.activo?'anular':'reactivar';if(!confirm(`¿Desea ${action} la rendición ${String(item.numero_rendicion).padStart(3,'0')}?`))return;loading.value=true;try{await cambiarEstadoRendicionCajaChica(item.id);success.value=`Rendición ${item.activo?'anulada':'reactivada'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blank());load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Rendiciones de caja chica</nav><header class="hero"><div class="mark">RC</div><div><small>MIA · FINANZAS · CAJA CHICA</small><h1>Rendiciones de caja chica</h1><p>Control de fondos fijos, gastos directos y anticipos por rendir.</p></div><strong>{{total}} rendiciones</strong><RouterLink class="new" to="/modulos/administracion/finanzas/rendiciones-caja-chica/nueva">+ Nueva rendición</RouterLink></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="filters.tipo_rendicion"><option value="">Todos los tipos</option><option value="FONDO_FIJO">Fondo fijo</option><option value="GASTO_DIRECTO">Gasto directo</option><option value="ANTICIPO_VIATICO">Anticipos - viáticos</option></select><select v-model="filters.tipo_fondo_caja_chica_id"><option value="">Todos los fondos</option><option v-for="x in funds" :key="x.id" :value="x.id">{{x.codigo}} · {{x.detalle}}</option></select><input v-model="filters.numero_rendicion" type="number" min="1" placeholder="Nro. rendición"><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron rendiciones de caja chica.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Tipo de rendición</th><th>Fondo</th><th>Nro.</th><th>Fecha</th><th>Referencia</th><th>Total</th><th>Estado</th><th>Contabilización</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td>{{typeName(item.tipo_rendicion)}}</td><td><b>{{item.tipo_fondo?.codigo}}</b><small>{{item.tipo_fondo?.detalle}}</small></td><td><b>{{String(item.numero_rendicion).padStart(3,'0')}}</b></td><td>{{date(item.fecha)}}</td><td>{{item.referencia||'-'}}</td><td class="number"><b>{{money(item.total_general)}}</b></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'ANULADA'}}</span></td><td><span :class="(item.estado_contabilizacion||'PENDIENTE').toLowerCase()">{{item.estado_contabilizacion||'PENDIENTE'}}</span><small>{{item.documentos_contabilizados||0}} / {{item.documentos_totales||0}} comprobantes</small><div class="progress"><i :style="{width:`${percent(item)}%`}"></i></div></td><td class="actions"><button @click="view(item)">Ver</button><RouterLink v-if="item.activo" :to="`/modulos/administracion/finanzas/rendiciones-caja-chica/${item.id}/editar`">Editar</RouterLink><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Anular':'Reactivar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1" class="pager"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>RENDICIÓN #{{String(detail.numero_rendicion).padStart(3,'0')}}</small><h2>{{typeName(detail.tipo_rendicion)}}</h2></div><span :class="detail.activo?'good':'bad'">{{detail.activo?'ACTIVA':'ANULADA'}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>FONDO</small><b>{{detail.tipo_fondo?.codigo}} · {{detail.tipo_fondo?.detalle}}</b></div><div><small>FECHA</small><b>{{date(detail.fecha)}}</b></div><div><small>REFERENCIA</small><b>{{detail.referencia||'-'}}</b></div><div><small>TOTAL GENERAL</small><b>{{money(detail.total_general)}}</b></div></div><h3>Documentos sustentatorios</h3><div v-if="!detail.documentos?.length" class="empty inner">Sin documentos registrados.</div><div v-else class="scroll"><table class="docs"><thead><tr><th>Documento</th><th>Fecha</th><th>Persona</th><th>Rubro / destino</th><th>Glosa</th><th>Total</th></tr></thead><tbody><tr v-for="doc in detail.documentos" :key="doc.id"><td><b>{{doc.tipo_documento_codigo}} {{doc.serie}}-{{doc.numero}}</b><small>{{doc.tipo_documento_detalle}}</small></td><td>{{date(doc.fecha_documento)}}</td><td>{{doc.nombre_persona}}</td><td>{{doc.rubro_codigo}} · {{doc.rubro_detalle}}<small>{{doc.destino_codigo}} · {{doc.destino_denominacion}}</small></td><td>{{doc.glosa}}</td><td class="number">{{money(doc.total)}}</td></tr></tbody></table></div></section></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small,.facts small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}.new,button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.new{text-decoration:none}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1.3fr 1.5fr .8fr 1fr 1fr auto auto;gap:7px;background:#fff}.filters label{display:flex;align-items:center;gap:4px;font-size:.46rem}.filters input,.filters select{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.48rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.47rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#809096}.number{text-align:right}.good,.bad,.pendiente,.parcial,.completa{display:inline-block;padding:4px 8px;border-radius:10px;font-size:.41rem;font-weight:800}.good,.completa{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.pendiente{color:#68777d;background:#edf1f2}.parcial{color:#8a6017;background:#fff2d7}.progress{width:105px;height:4px;margin-top:4px;background:#e4eaec}.progress i{display:block;height:100%;background:var(--a)}.actions{display:flex;gap:5px}.actions a{padding:8px 11px;border-radius:6px;color:#fff;background:var(--a);text-decoration:none}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.pager{padding:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.5rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(1050px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;gap:8px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.facts div{display:grid;gap:4px;padding:10px;background:#f1f6f7}.dialog h3{font-size:.65rem}.docs{min-width:900px}.inner{padding:25px}@media(max-width:900px){.filters{grid-template-columns:repeat(2,1fr)}.facts{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.filters,.facts{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
